/*
  DevsAssemble brand system — comic-book "Avengers Assemble" energy.
  Palette pulled from the logo: electric blue (DEVS), lime (ASSEMBLE),
  purple (shadow / .AI), heavy black ink outlines, warm cream paper.
*/
:root {
  --background: #f7f1e3; /* cream paper from the icon plate */
  --foreground: #0a0a0a; /* ink */

  --brand-blue: #2f6bff;
  --brand-blue-ink: #1b3fb0;
  --brand-lime: #a6e22e;
  --brand-lime-ink: #6f9e12;
  --brand-purple: #6d28d9;
  --brand-purple-ink: #4c1d95;
  --brand-ink: #0a0a0a;
  --brand-cream: #f7f1e3;

  --surface: #ffffff;
  --muted: #6b6b6b;
  --border: #0a0a0a;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);

  --color-brand-blue: var(--brand-blue);
  --color-brand-blue-ink: var(--brand-blue-ink);
  --color-brand-lime: var(--brand-lime);
  --color-brand-lime-ink: var(--brand-lime-ink);
  --color-brand-purple: var(--brand-purple);
  --color-brand-purple-ink: var(--brand-purple-ink);
  --color-brand-ink: var(--brand-ink);
  --color-brand-cream: var(--brand-cream);

  --color-surface: var(--surface);
  --color-muted: var(--muted);
  --color-border: var(--border);

  --font-sans: var(--font-body);
  --font-display: var(--font-display);
  --font-mono: var(--font-geist-mono);

  --radius-comic: 0.75rem;
}

