  box-shadow: 2px 2px 0 0 var(--brand-ink);
}

/* Heavy ink outline used on cards, buttons, badges. */
@utility border-ink {
  border: 3px solid var(--brand-ink);
}

/* Chunky comic text stroke for display headings. */
@utility text-stroke-ink {
  -webkit-text-stroke: 2px var(--brand-ink);
  paint-order: stroke fill;
}

