/** The DevsAssemble wordmark. Uses the full header art; `icon` uses the DA badge. */
export function Logo({
  variant = "wordmark",
  className,
  priority,
}: {
  variant?: "wordmark" | "icon";
  className?: string;
  priority?: boolean;
}) {
  const src = variant === "icon" ? "/logo-icon.png" : "/logo-header.png";
  const dims =
