import Link from "next/link";
import type { ComponentProps, ReactNode } from "react";

type Variant = "blue" | "lime" | "purple" | "ink";

const VARIANTS: Record<Variant, string> = {
  blue: "bg-brand-blue text-white",
  lime: "bg-brand-lime text-brand-ink",
  purple: "bg-brand-purple text-white",
  ink: "bg-brand-ink text-white",
};

const base =
  "inline-flex items-center justify-center gap-2 rounded-[var(--radius-comic)] border-ink px-6 py-3 font-display text-lg uppercase tracking-wide shadow-comic transition-transform duration-100 hover:-translate-x-0.5 hover:-translate-y-0.5 hover:shadow-comic-lg active:translate-x-0.5 active:translate-y-0.5 active:shadow-comic-sm";

/** A chunky comic-styled button. Renders an <a> when `href` is set, else a <button>. */
export function ComicButton({
  children,
  variant = "blue",
  className = "",
  href,
  ...props
}: {
  children: ReactNode;
  variant?: Variant;
  className?: string;
  href?: string;
} & Omit<ComponentProps<"button">, "className">) {
  const classes = `${base} ${VARIANTS[variant]} ${className}`;

  if (href) {
    return (
      <Link href={href} className={classes}>
        {children}
      </Link>
    );
  }

  return (
    <button className={classes} {...props}>
      {children}
    </button>
  );
}

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";

/**
 * Supabase client for Server Components, Server Actions, and Route Handlers.
 * Reads the user's session from cookies and enforces RLS as the authed user.
 * `cookies()` is async in Next.js 16.
 */
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options),
            );
          } catch {
            // `setAll` was called from a Server Component. This can be ignored
            // when the session refresh runs in proxy.ts (which it does).
          }
        },
      },
    },
  );
}

import { createBrowserClient } from "@supabase/ssr";

/**
 * Supabase client for Client Components (Realtime event chat, optimistic
 * like toggles). Enforces RLS as the authed user via the session cookie.
 */
export function createClient() {
  return createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
  );
}

import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";

/**
 * Refreshes the Supabase auth session on every request and syncs cookies.
 * Called from the root `proxy.ts` (Next.js 16 renamed `middleware` -> `proxy`).
 *
 * IMPORTANT: do not run auth/database logic here beyond the session refresh —
 * proxy runs on prefetches too. Route protection lives in the DAL
 * (`lib/auth/dal.ts`), close to the data.
 */
export async function updateSession(request: NextRequest) {
  let response = NextResponse.next({ request });

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) =>
            request.cookies.set(name, value),
          );
          response = NextResponse.next({ request });
          cookiesToSet.forEach(({ name, value, options }) =>
            response.cookies.set(name, value, options),
          );
        },
      },
    },
  );

  // Touch the user to trigger a token refresh when needed. Do not remove.
  await supabase.auth.getUser();

  return response;
}

import "server-only";

import { createClient } from "@supabase/supabase-js";

/**
 * Service-role Supabase client — BYPASSES Row Level Security.
 *
 * Use ONLY in trusted server code that must act with elevated privileges:
 * cron route handlers (event reminders), webhook processors, and moderation
 * tooling. Never import this into a Client Component or expose the key.
 */
export function createAdminClient() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    { auth: { autoRefreshToken: false, persistSession: false } },
  );
}

import { type NextRequest } from "next/server";
import { updateSession } from "@/lib/supabase/proxy";

/**
 * Next.js 16 Proxy (formerly `middleware`). Runs on the Node.js runtime.
 * Responsibility here is intentionally narrow: refresh the Supabase session
 * and sync auth cookies. Security headers/CSP are applied in `next.config.ts`,
 * and route authorization happens in the DAL close to the data.
 */
export async function proxy(request: NextRequest) {
  return updateSession(request);
}

export const config = {
  matcher: [
    /*
     * Match all paths except static assets and image files, so auth cookies
     * stay fresh on navigations without blocking CSS/JS/images.
     */
    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:png|jpg|jpeg|gif|svg|webp|ico)$).*)",
  ],
};

import "server-only";

import { cache } from "react";
import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

export type Role = "member" | "moderator" | "admin";

export type SessionUser = {
  id: string;
  email: string | null;
  role: Role;
  username: string | null;
  displayName: string | null;
  avatarUrl: string | null;
  isBanned: boolean;
};

/**
 * Data Access Layer. Following the Next.js 16 auth guidance, authorization
 * checks live here (close to the data) rather than in a layout or proxy.
 * `cache` memoizes the lookup for a single render pass.
 */
export const getSessionUser = cache(async (): Promise<SessionUser | null> => {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;

  const { data: profile } = await supabase
    .from("profiles")
    .select("role, username, display_name, avatar_url, is_banned")
    .eq("id", user.id)
    .single();

  return {
    id: user.id,
    email: user.email ?? null,
    role: (profile?.role as Role) ?? "member",
    username: profile?.username ?? null,
    displayName: profile?.display_name ?? null,
    avatarUrl: profile?.avatar_url ?? null,
    isBanned: profile?.is_banned ?? false,
  };
});

/** Require an authenticated, non-banned user or redirect to /login. */
export async function requireUser(): Promise<SessionUser> {
  const user = await getSessionUser();
  if (!user) redirect("/login");
  if (user.isBanned) redirect("/banned");
  return user;
}

/** Require a moderator or admin, or send unauthorized users home. */
export async function requireAdmin(): Promise<SessionUser> {
  const user = await requireUser();
  if (user.role !== "admin" && user.role !== "moderator") redirect("/");
  return user;
}

